from pathlib import Path
from textwrap import dedent

base = Path(__file__).resolve().parent
docs = base / 'docs'


def prepend(path: Path, text: str) -> None:
    original = path.read_text()
    path.write_text(text + original)

README_ADD = "## Revision addendum after rev0497 — bounded-exposure remediation and remedial leak-budget ceiling\n\nThis continuation archive advances the doctrine by tightening one sharper seam before the already-visible clean-state frontier:\n**what happens after a late outsider can trust the corrected replacement and even act from it without operator help, but before the product may honestly pretend that this remediation path stays within the reviewed disclosure, authority, forwarding, and retention budget instead of quietly widening exposure through bearer links, onward resharing, owner grants, or durable local residue**.\nIt does eight things in one tranche:\n\n1. Continues the archive after rev0497 with a new page family centered on whether outsider self-service remediation is also bounded, reviewable, and exposure-safe.\n2. Tightens the non-clone line again: borrow Resilio's candor about single-file bearer links, optional expiration, unlimited device/use for file links, recipient forwarding, Standard-folder unlimited resharing, Owner-only Advanced resharing, approval settings, click-count limits, and disconnect residue; refuse any contract where the operator still has to reconstruct `can this outsider remediate without creating wider uncontrolled exposure?` from scattered sharing, transfer, permission, and retention pages.\n3. Adds one new **Resilio evaluation** document focused on why current bounded-exposure remediation and remedial leak-budget truth are still too fragmented to clone even though the ingredients are useful.\n4. Adds five new **interface specs** for remediation-exposure contract sheet, review, proof, timeline, and lineage receipt.\n5. Makes one hard product decision explicit: **outsider actionable reliance and operator-free remediation are weaker than bounded-exposure remediation and remedial leak-budget truth.**\n6. Makes another hard product decision explicit: **a self-service remedy path that only works by widening audience, resharing rights, or durable uncontrolled residue is weaker than a narrower but honestly bounded remedy path.**\n7. Makes a third hard product decision explicit: **non-expiring bearer links, unlimited-use downloads, onward resharing, owner grants, and local-retention residue are not allowed to impersonate `safe outsider self-service remediation`.**\n8. Packages the result as another continuation archive whose new tranche makes the `remediation carrier / audience breadth / onward-reshare class / retention residue class / exposure budget / strongest honest safe-remedy sentence / blocked stronger bounded-exposure sentence` seam explicit in the reading order and page family.\n\nNew docs in this tranche:\n\n- `2128-resilio-remedy-hardening-attestation-outsider-bounded-remediation-and-remedial-exposure-budget-fragmentation-evaluation.md`\n- `2129-remedy-hardening-attestation-remediation-exposure-contract-sheet-page-self-service-path-bearer-breadth-and-reshare-ceiling-interface-spec.md`\n- `2130-remedy-hardening-attestation-remediation-exposure-review-page-can-a-late-outsider-remediate-without-widening-exposure-beyond-budget-interface-spec.md`\n- `2131-remedy-hardening-attestation-remediation-exposure-proof-page-carrier-breadth-retention-residue-and-safe-action-sentence-ceiling-interface-spec.md`\n- `2132-remedy-hardening-attestation-remediation-exposure-timeline-page-corrected-published-opened-forwarded-connected-downloaded-and-exposure-horizon-closed-events-interface-spec.md`\n- `2133-remedy-hardening-attestation-remediation-exposure-lineage-receipt-page-safe-self-service-summary-exposure-budget-and-blocked-stronger-truth-sentences-interface-spec.md`\n\n"
STATUS_ADD = '## rev0498 — bounded-exposure remediation and remedial leak-budget ceiling\n\nThis tranche adds one more hard line to the doctrine:\n\n- **outsider actionable reliance and operator-free remediation are weaker than bounded-exposure remediation and remedial leak-budget truth**\n- **a self-service remedy path is weaker than a self-service remedy path that stays within the reviewed disclosure, authority, forwarding, and retention budget**\n- **bearer-link breadth, onward resharing, permission widening, and durable local residue are different truths from outsider-safe remediation**\n- **required carrier, audience breadth, resharing class, expiry/click posture, and retention residue must stay explicit instead of dissolving into `the outsider can fix this themselves` folklore**\n\nWhat this tranche contributes to the larger doctrine:\n\n- `the outsider can act from this corrected thing` can no longer silently stand in for `the outsider can act from it without widening exposure beyond budget`\n- `a link works and the outsider can download` can no longer silently stand in for `the remedy path is safely bounded`\n- `approval exists somewhere` can no longer silently stand in for `onward spread and permission widening are contained`\n- `the correction can be delivered by a bearer path` can no longer silently stand in for `the remedial carrier does not create a new public residue problem`\n- operator-free remediation can no longer silently stand in for exposure-safe remediation\n\nWhat remains intentionally true:\n\n- outsider actionability still matters\n- supersession trust still matters\n- public-claim repair and audience stale-dependency retirement still matter\n- but none of those may substitute for one explicit answer about whether a late outsider can remediate from the corrected thing without blowing past the reviewed exposure budget\n\nNew docs added in this tranche:\n\n- `2128-resilio-remedy-hardening-attestation-outsider-bounded-remediation-and-remedial-exposure-budget-fragmentation-evaluation.md`\n- `2129-remedy-hardening-attestation-remediation-exposure-contract-sheet-page-self-service-path-bearer-breadth-and-reshare-ceiling-interface-spec.md`\n- `2130-remedy-hardening-attestation-remediation-exposure-review-page-can-a-late-outsider-remediate-without-widening-exposure-beyond-budget-interface-spec.md`\n- `2131-remedy-hardening-attestation-remediation-exposure-proof-page-carrier-breadth-retention-residue-and-safe-action-sentence-ceiling-interface-spec.md`\n- `2132-remedy-hardening-attestation-remediation-exposure-timeline-page-corrected-published-opened-forwarded-connected-downloaded-and-exposure-horizon-closed-events-interface-spec.md`\n- `2133-remedy-hardening-attestation-remediation-exposure-lineage-receipt-page-safe-self-service-summary-exposure-budget-and-blocked-stronger-truth-sentences-interface-spec.md`\n\n## Current frontier after rev0498 — outsider remediation completion and self-verifying clean-state truth\n\nThe next seam after **bounded-exposure remediation and remedial leak-budget truth** is now explicit:\n\n- the archive can already say whether the corrected replacement is discoverable and intelligible\n- it can already say whether a late outsider can act from that surface without operator help\n- it can now say whether that self-service path stays within the reviewed exposure budget instead of quietly widening audience or residue\n- it still needs to own the harder truth of **whether the outsider actually completed remediation, retired their stale local residue, and can verify that clean state without reopening the operator-support loop**\n\nThis pass therefore keeps the next visible step explicit: **outsider remediation completion and self-verifying clean-state truth**.\n\n'
RESILIO_ADD = "## Revision addendum after rev0497 — why bounded-exposure remediation and remedial leak-budget truth now sit on the non-clone side\n\nCurrent official Resilio docs are still admirably candid that `the outsider can trust the corrected replacement`, `the outsider can open a remediation path`, `the outsider can download or connect`, and `the remediation path stays within the reviewed exposure budget` are not one flat truth.\n`Sharing single file` still says a generated file-transfer link can be made never-expiring, is valid for three days by default when expiration is used, everyone who gets the link can download the shared files, there is no option to restrict the number of uses or ban devices, recipients can share the received files further, and removing the file from Sync UI does not remove it from the device.\n`Sync Share Dialog (Desktop)` still says folder-share links can be copied into e-mail or messengers, approval may be disabled so syncing starts automatically, approvals may be limited to new peers or required for all peers, the link can expire after N days, and the link can be clicked only N times before further connection attempts fail.\n`What's the difference between Standard and Advanced folders?` still says only Owners can share Advanced folders onward, while Standard-folder peers can share the key they have without limitation.\n`User Management` still says all devices linked under one identity act as Owners, only Owners may invite new users to Advanced folders, and disconnecting a peer suspends future updates while files already synchronized so far remain in the folder.\n`Link structure and flow` still says links are designed to be opened from a landing page that hands off into the app or can be added manually, which is good for reach but still separate from any first-class exposure-budget answer.\n\nThis is useful implementation candor.\nIt is also exactly why AnonSync should not clone the present contract.\nOne ordinary answer to `if a late outsider can remediate from the corrected thing, did that remediation path stay within the reviewed leak budget?` still depends on combining file-transfer bearer-link rules, folder-share approval controls, standard-versus-advanced resharing rules, linked-device owner widening, click limits, expiration knobs, and residual local-retention facts scattered across separate pages.\n\nSo this tranche freezes a stronger replacement line: **remediation carrier class / audience breadth / onward-reshare class / permission-widening class / retention-residue class / strongest honest safe-remedy sentence** must be first-class and rendered together.\n\n"
PRODUCT_ADD = '## Product-direction addendum after rev0497 — outsider actionability must graduate into bounded-exposure remediation\n\nAnonSync should not let a self-service-looking remedy path masquerade as a safely bounded remedy path.\nThe product direction is now explicit:\n\n- every correction flow that claims outsider self-service must also state the carrier by which the outsider remediates (`bounded invite`, `approval-gated folder link`, `bearer folder link`, `one-time file-transfer link`, `forwarded copy`, `other`)\n- every remedy-bearing carrier must declare audience breadth, onward-reshare class, permission-widening class, and retention-residue class separately\n- the strongest sentence engine must preserve the difference between `outsider can remediate`, `outsider can remediate via a bearer path`, and `outsider can remediate within the reviewed exposure budget`\n- expiry, click limits, approval requirements, and owner-only sharing must remain visible as budget components instead of being buried in auxiliary security drawers\n- the receipt family must stay portable enough that a later reader can tell whether safe remediation depends on bounded invitation, owner-only share topology, narrow retention, or uncontrolled bearer residue\n\nThat means future interface work should keep one stable family for:\n\n- remediation carrier class\n- audience breadth and carrier reach\n- onward-reshare class\n- permission-widening class\n- retention-residue class\n- strongest honest safe-remedy sentence ceiling\n\nThe product should never force the operator to infer those truths from a convenience share dialog, a default expiration checkbox, a hidden click-limit knob, a bearer-download success, or the mere fact that the outsider eventually got the corrected bytes.\n\n'
SOURCES_ADD = "## rev0498 source set — bounded-exposure remediation and remedial leak-budget truth\n\nThe most load-bearing source set for this pass was:\n\n- Resilio's current `Sharing single file` article, which still says file-transfer links can be made never-expiring, are valid for three days by default when expiration is used, everyone with the generated link can download the shared files, there is no option to restrict number of uses or ban devices, recipients can share the files further, and removing the file from Sync UI does not remove it from the device.\n- Resilio's current `Sync Share Dialog (Desktop)` article, which still says folder links can be copied into e-mail or messengers, approval may be disabled so syncing starts automatically, approvals may be limited to new peers or required for all peers, and links can have both an expiration period and a click-count limit.\n- Resilio's current `What's the difference between Standard and Advanced folders?` article, which still says only Owners can share Advanced folders onward while Standard-folder peers can share the key they have without limitation.\n- Resilio's current `User Management` article, which still says all devices linked under one identity act as Owners, Owners can invite new users, and disconnect suspends future updates while already synchronized files remain in the folder.\n- Resilio's current `Link structure and flow` article, which still says links are handed through a landing page into the app or added manually, reinforcing that remediation reach and exposure budget are separate questions.\n\nThose sources were enough to tighten the line again:\n\n- current Resilio still deserves credit for candid exposure-control ingredients\n- but current Resilio still answers `can a late outsider remediate from the corrected thing without widening exposure beyond budget?` too diffusely\n- AnonSync should therefore prefer explicit remediation-exposure contract sheets, remediation-exposure reviews, remediation-exposure proofs, remediation-exposure timelines, and durable remediation-exposure lineage receipts over overloaded share dialogs, bearer-link defaults, permission folklore, and after-the-fact residue assumptions\n\nPrimary sources:\n\n- Sharing single file\n  https://help.resilio.com/hc/en-us/articles/115000401010-Sharing-single-file\n\n- Sync Share Dialog (Desktop)\n  https://help.resilio.com/hc/en-us/articles/204790709-Sync-Share-Dialog-Desktop\n\n- What's the difference between Standard and Advanced folders?\n  https://help.resilio.com/hc/en-us/articles/204754679-What-s-the-difference-between-Standard-and-Advanced-folders\n\n- User Management\n  https://help.resilio.com/hc/en-us/articles/205471375-User-Management\n\n- Link structure and flow\n  https://help.resilio.com/hc/en-us/articles/204754739-Link-structure-and-flow\n\n"
DOCS = {'2128-resilio-remedy-hardening-attestation-outsider-bounded-remediation-and-remedial-exposure-budget-fragmentation-evaluation.md': "# Resilio remedy-hardening attestation outsider bounded remediation and remedial exposure budget fragmentation evaluation\n\n## Why this seam matters now\n\nThe archive can already say:\n\n- the corrected replacement is discoverable\n- the corrected replacement explains why it supersedes the stale thing\n- a late outsider may trust that successor claim\n- a late outsider may even have a usable self-service remediation path\n\nThat is still weaker than a harder question:\n\n**if the late outsider remediates from that surface, does the remedy path stay within the reviewed disclosure, authority, forwarding, and retention budget, or did the product buy self-service by quietly widening exposure?**\n\nActionability is not yet bounded safety.\nA remedy path can be self-service and still be too broad.\nWithout an explicit leak-budget contract, `they can fix themselves from here` quietly expands into folklore about `and this was a safe way to let them do it`.\n\n## Why current Resilio still leaves this too diffuse to clone\n\nCurrent official Resilio material is candid about several exposure-shaping ingredients, but it still spreads them across separate pages:\n\n- `Sharing single file` says a generated file-transfer link can be made never-expiring, everyone who gets the link can download the files, there is no option to restrict number of uses or devices, recipients can share the files further, and removing the file from Sync UI does not remove it from the device\n- `Sync Share Dialog (Desktop)` says folder-share links can be copied into e-mail or messengers, approval can be disabled so syncing starts automatically, approvals can be limited to new peers or required for all peers, and the link can have expiration and click-count limits\n- `What's the difference between Standard and Advanced folders?` says only Owners can share Advanced folders onward, while Standard-folder peers can share the key they have without limitation\n- `User Management` says all linked devices under one identity act as Owners, Owners can invite new users, and disconnecting a peer stops future updates while already synchronized files remain in the folder\n- `Link structure and flow` says links are designed for easy handoff through a landing page into the app or for manual addition, which is reach-friendly but not itself a bounded-exposure verdict\n\nThis is good implementation candor.\nIt is not yet one first-class answer to **if the outsider can remediate, what audience breadth, onward spread, permission widening, and durable residue did that remediation path carry with it?**\n\n## The non-clone line\n\nAnonSync should not clone a contract where all of these are allowed to blur together:\n\n- the outsider can trust the corrected replacement\n- the outsider can reach a working remediation carrier\n- the remediation carrier is a bearer link anyone can reuse\n- the carrier may never expire or may allow broad forwarding\n- some permission topology may let the recipient widen access further\n- already delivered copies may remain after disconnect or UI removal\n- the outsider therefore had a safe remediation path\n\nThose are separate truths.\n\n## Product decision frozen in this tranche\n\nThis revision freezes a stronger line:\n\n- **outsider actionable reliance and operator-free remediation are weaker than bounded-exposure remediation and remedial leak-budget truth**\n- **a self-service remedy path that quietly broadens audience, resharing, or residue is weaker than a narrower but honestly bounded remedy path**\n- **bearer-link convenience, unlimited downloadability, owner-right widening, or local-retention residue may never impersonate `safe outsider self-service remediation`**\n\n## What AnonSync should model explicitly instead\n\nAnonSync should add one first-class family for:\n\n- remediation carrier class\n- audience breadth class\n- onward-reshare class\n- permission-widening class\n- expiry and click-budget class\n- retention-residue class\n- strongest honest safe-remedy sentence\n- blocked stronger bounded-exposure sentence\n\n## Interface consequence\n\nThat is why this tranche adds five more first-class pages:\n\n- **remediation-exposure contract sheet**\n- **remediation-exposure review**\n- **remediation-exposure proof**\n- **remediation-exposure timeline**\n- **remediation-exposure lineage receipt**\n", '2129-remedy-hardening-attestation-remediation-exposure-contract-sheet-page-self-service-path-bearer-breadth-and-reshare-ceiling-interface-spec.md': '# Remedy-hardening-attestation remediation-exposure contract sheet page — self-service path, bearer breadth, and reshare ceiling\n\n## Purpose\n\nThis page is the operator-facing contract sheet for deciding whether a late outsider can remediate from the corrected replacement **without widening exposure beyond the reviewed budget**.\nIt exists to stop `this surface lets them fix themselves` from being mistaken for `this surface lets them fix themselves safely`.\n\n## Core question\n\nThe page must answer:\n\n**what is the strongest honest sentence we can make about safe outsider remediation now, and what stronger bounded-exposure sentence is still blocked?**\n\n## Required fields\n\nThe contract sheet must capture at least:\n\n- stale artifact identifier\n- corrected replacement identifier\n- remediation carrier class\n- audience breadth class\n- onward-reshare class\n- permission-widening class\n- expiry / click-budget class\n- approval posture\n- retention-residue class\n- exposure budget verdict\n- strongest honest safe-remedy sentence\n- blocked stronger bounded-exposure sentence\n\n## Remediation carrier classes\n\nThe sheet must preserve at least:\n\n- bounded invite only\n- approval-gated folder link\n- bearer folder link\n- one-time file-transfer link\n- forwarded local copy\n- owner-grant path\n- mixed carrier path\n- unknown carrier\n\n## Exposure-budget panel\n\nThe page must force explicit answers to:\n\n- who can use the carrier if it is forwarded beyond the intended outsider?\n- can the carrier be reused without a per-device or per-use ceiling?\n- can the outsider share onward, invite others, or widen permissions?\n- can already delivered copies survive disconnect, UI removal, or later revocation?\n- does the path rely on a narrower carrier in one environment but a bearer carrier in another?\n\n## Residue panel\n\nThe sheet must keep separate:\n\n- carrier no longer usable for new connections\n- previously delivered bytes still present\n- recipient can forward copy further\n- recipient can widen authority further\n- exposure retired elsewhere\n\n## Hard rules\n\nThe page must never allow:\n\n- `outsider can remediate` to silently stand in for `outsider can remediate within budget`\n- expiration alone to erase already delivered residue\n- approval gates to erase onward-sharing rights once granted\n- one narrow carrier to hide that another named path is still bearer-broad\n', '2130-remedy-hardening-attestation-remediation-exposure-review-page-can-a-late-outsider-remediate-without-widening-exposure-beyond-budget-interface-spec.md': '# Remedy-hardening-attestation remediation-exposure review page — can a late outsider remediate without widening exposure beyond budget?\n\n## Purpose\n\nThis page is the review surface for forcing the operator to confront whether outsider self-service remediation is also bounded and exposure-honest.\nIt exists to prevent the archive from settling for `they can fix themselves from here` when the harder question is `what does that path leak, widen, or leave behind?`\n\n## Review question\n\nThe review must force a direct answer to:\n\n**if a late outsider uses the corrected replacement to remediate stale reliance, does the path stay within the reviewed audience, authority, and retention budget, or does it create broader exposure?**\n\n## Required review prompts\n\nThe page must ask at least:\n\n- what carrier does the outsider use to remediate?\n- who else could use that carrier if it is forwarded?\n- does the carrier expire, click out, or remain indefinitely reusable?\n- can the outsider reshare the delivered material or widen permissions further?\n- what copies remain after disconnect, UI removal, expiration, or revocation?\n- what stronger safe-remedy sentence would be false if rendered now?\n\n## Required comparison panel\n\nThe review must keep side-by-side:\n\n- self-service remedy versus bounded self-service remedy\n- approval-gated path versus bearer path\n- expiring carrier versus durable delivered residue\n- read-only delivery versus onward-share or owner-widening potential\n- strongest honest safe-remedy sentence versus blocked stronger sentence\n\n## Interaction requirements\n\nThe reviewer must be able to:\n\n- click any carrier and see its audience breadth, reuse ceiling, and residue implications separately\n- open a resharing drawer that shows whether forwarding copies, keys, or permissions can widen exposure\n- downgrade the strongest sentence in one gesture when any leak-budget component goes red\n- compare Standard-folder, Advanced-folder, and single-file paths without losing sentence distinctions\n\n## Hard rules\n\nThe page must never allow:\n\n- `late outsider can remediate` to render as `late outsider can remediate safely`\n- approval posture to hide that a bearer file link remains broadly reusable\n- expiration or click limits to hide already delivered copy residue\n- one narrow folder path to erase that the file-transfer fallback is uncontrolled\n', '2131-remedy-hardening-attestation-remediation-exposure-proof-page-carrier-breadth-retention-residue-and-safe-action-sentence-ceiling-interface-spec.md': "# Remedy-hardening-attestation remediation-exposure proof page — carrier breadth, retention residue, and safe action sentence ceiling\n\n## Purpose\n\nThis page is the evidence-heavy surface for proving what exposure budget a late outsider's remediation path actually consumed.\nIt exists to preserve carrier breadth, resharing rights, delivered-copy residue, and blocked stronger sentences instead of collapsing everything into a vague `self-service remediation succeeded` claim.\n\n## Core proof question\n\nThe page must answer:\n\n**what is the strongest evidence-backed sentence we can honestly make about bounded outsider remediation now, and what stronger bounded-exposure sentence is still blocked?**\n\n## Minimum evidence sections\n\nThe proof page must contain:\n\n- receipt header\n- carrier and reach ledger\n- permission-widening ledger\n- retention-residue ledger\n- budget-exception ledger\n- strongest honest sentence / blocked stronger sentence panel\n\n## Receipt header\n\nThe header must show:\n\n- action identifier\n- stale artifact identifier\n- corrected replacement identifier\n- proof freshness timestamp\n- current remediation-exposure standing\n\n## Carrier and reach ledger\n\nFor each named carrier show:\n\n- carrier class\n- intended outsider set\n- effective audience breadth\n- reuse ceiling\n- expiry or click ceiling\n- same-surface versus forwarded use\n- exclusions\n\nThe ledger must make it impossible to merge `carrier exists`, `carrier works`, and `carrier is bounded`.\n\n## Permission-widening ledger\n\nFor each path show:\n\n- can recipient reshare copy\n- can recipient reshare key or link\n- can recipient invite others\n- can recipient widen to owner-level control\n- what topology makes that widening possible\n\n## Retention-residue ledger\n\nTrack at least:\n\n- delivered bytes remain after UI removal\n- delivered bytes remain after disconnect\n- already forwarded copies untracked\n- previously approved peer still present elsewhere\n- residue retirement proven elsewhere\n\nEvery residue item must carry:\n\n- why it remains open\n- what sentence it blocks\n- whether it is carrier-specific or universal\n\n## Budget-exception ledger\n\nTrack at least:\n\n- unlimited-use bearer download\n- no device restriction\n- onward forwarding allowed\n- owner-right widening possible\n- expiration absent or disabled\n- click budget absent or exceeded\n- revocation stops updates only\n- local residue survives revocation\n\n## Hard rules\n\nThe page must never allow:\n\n- successful outsider remediation to erase exposure exceptions\n- expired carrier to erase delivered-copy residue\n- approval history to erase onward rights already granted\n- one bounded path to hide another uncontrolled path\n", '2132-remedy-hardening-attestation-remediation-exposure-timeline-page-corrected-published-opened-forwarded-connected-downloaded-and-exposure-horizon-closed-events-interface-spec.md': '# Remedy-hardening-attestation remediation-exposure timeline page — corrected published, opened, forwarded, connected, downloaded, and exposure horizon closed events\n\n## Purpose\n\nThis page is the chronological surface for showing how outsider remediation and exposure budget changed over time.\nIt exists to stop the archive from flattening `a late outsider could remediate` into `the remediation path stayed safely bounded throughout the exposure horizon`.\n\n## Core question\n\nThe timeline must answer:\n\n**across the exposure horizon, when did the corrected replacement become self-service, when did that path remain bounded, and when did forwarding, permission widening, or durable residue reopen exposure beyond budget?**\n\n## Required event classes\n\nThe timeline must support at least:\n\n- corrected replacement published\n- remediation carrier issued\n- approval posture changed\n- outsider opened carrier\n- outsider connected or downloaded\n- outsider forwarded carrier or copy\n- permission widened\n- peer disconnected or revoked\n- residue retired\n- exposure exception discovered\n- exposure horizon closed\n- receipt superseded\n\n## Required lanes\n\nThe page must show at least these lanes:\n\n- carrier issuance lane\n- outsider remediation lane\n- forwarding and widening lane\n- residue retirement lane\n- sentence-ceiling lane\n\n## Per-event payload\n\nEvery event must preserve:\n\n- event timestamp\n- actor or subsystem\n- affected carrier or surface\n- exposure consequence\n- evidence source\n- sentence consequence\n\n## Visual rules\n\nThe timeline must make these differences obvious:\n\n- remediation available versus remediation bounded\n- approval gate changed versus exposure retired\n- download complete versus residue retired\n- revocation of future updates versus removal of prior copies\n- quiet period versus positive proof that leak budget is closed\n\n## Required overlays\n\nThe interface must support overlays for:\n\n- effective audience breadth over time\n- permission-widening posture over time\n- residue count over time\n- strongest honest safe-remedy sentence changes\n\n## Hard rules\n\nThe page must never allow:\n\n- a remediation event to silently stand in for an exposure-safe event\n- a revocation event to silently stand in for residue retirement\n- a single narrow download to silently stand in for horizon-wide boundedness\n- a quiet period to silently stand in for closed leak budget\n', '2133-remedy-hardening-attestation-remediation-exposure-lineage-receipt-page-safe-self-service-summary-exposure-budget-and-blocked-stronger-truth-sentences-interface-spec.md': '# Remedy-hardening-attestation remediation-exposure lineage receipt page — safe self-service summary, exposure budget, and blocked stronger truth sentences\n\n## Purpose\n\nThis page is the portable receipt for carrying the bounded-remediation verdict into later review, audit, or dispute contexts.\nIt exists so that a later reader can tell, without reopening the whole proof stack, whether a late outsider could remediate stale reliance from the corrected surface **without widening exposure beyond the reviewed budget**.\n\n## Core output\n\nThe receipt must answer:\n\n**what is the strongest honest sentence we can carry forward about safe outsider remediation now, and what stronger bounded-exposure sentence remains blocked?**\n\n## Required header fields\n\nShow at least:\n\n- receipt identifier\n- action identifier\n- stale artifact identifier\n- corrected replacement identifier\n- proof freshness timestamp\n- current remediation-exposure standing\n\n## Mandatory summary block\n\nThe summary block must include:\n\n- remediation carrier class\n- audience breadth class\n- onward-reshare class\n- permission-widening class\n- expiry / click-budget class\n- retention-residue class\n- highest-risk open leak-budget exception\n- strongest honest safe-remedy sentence\n- blocked stronger bounded-exposure sentence\n\n## Mandatory sentence ladder\n\nThe receipt must preserve at least these separations:\n\n- outsider can trust the correction only\n- outsider can remediate but carrier is bearer-broad\n- outsider can remediate under approval gate only\n- outsider can remediate and forwarding remains open\n- outsider can remediate on one bounded path only\n- broader bounded-exposure sentence blocked\n- remediation completion still separate\n\n## Mandatory blocker block\n\nFor every blocked stronger sentence show:\n\n- blocker name\n- blocker class\n- affected carrier or surface\n- whether the blocker is audience breadth, resharing, permission widening, or residue\n- what stronger sentence it prevents\n\n## Mandatory provenance block\n\nThe receipt must preserve:\n\n- who assembled the exposure proof\n- what evidence sources were used\n- which boundedness claims are direct proof\n- which boundedness claims are inference only\n- when the exposure horizon is considered to end\n\n## Interaction requirements\n\nThe receipt must support:\n\n- expanding any blocker into full proof detail\n- opening the remediation-carrier map from the summary chip\n- comparing this receipt against the earlier actionable-remedy receipt without losing sentence distinctions\n- exporting a compact version that still keeps the blocked stronger sentence visible\n'}

prepend(base / 'README.md', README_ADD)
prepend(docs / '00-status.md', STATUS_ADD)
prepend(docs / '10-resilio-sync-evaluation.md', RESILIO_ADD)
prepend(docs / '20-product-direction.md', PRODUCT_ADD)
prepend(docs / 'sources.md', SOURCES_ADD)
for name, text in DOCS.items():
    (docs / name).write_text(text)
